7675c621-98d5-4328-8288-e580a7c6a7a6	2026-05-26 08:03:59+00	git	fix: change ALLOWED_ORIGINS to str to prevent pydantic-settings JSONDecodeError	pydantic-settings 2.2.1 calls json.loads() on List[str] fields at the\nenv source layer before any field_validator runs. A plain string env\nvar like "*" is not valid JSON so it crashes on startup. Changing the\ntype to str makes pydantic treat it as a raw string — no JSON parsing,\nno crash. CORS middleware in main.py already uses ["*"] directly.\n\nCo-Authored-By: Claude Sonnet 4.6 <noreply@anthropic.com>	episodic	null	\N	0.6	[-0.009807837,0.03138567,-0.06332772,-0.08016677,-0.0047642454,-0.05391434,-0.1232402,0.08450823,-0.07834734,-0.00818793,-0.01515088,-0.0057937256,0.011458057,0.06468472,0.1083562,0.08555365,-0.06871782,-0.06536496,0.040343218,-0.023719475,-0.050657097,0.08449924,0.048404608,0.07094805,-0.061527364,-0.03254651,0.0039523165,0.06512682,-0.0057213106,0.049666993,0.03865906,0.06313181,-0.037729453,0.026242986,0.095702544,0.12066095,-0.022661425,-0.06566686,0.034473762,0.05188168,0.06801234,-0.0093706725,-0.04755402,-0.02556332,-0.079208024,0.027023714,0.05076044,0.045265585,0.060378622,-0.014104589,0.0008845299,0.09046491,0.069392376,-0.086214736,0.0016026854,-0.040170748,-0.06356822,0.018068422,0.018700771,-0.06753585,0.0028624428,0.035596874,-0.017068705,0.030075286,-0.07557565,0.03500058,0.010788328,-0.03675023,-0.0022286314,-0.01272323,0.066661745,-0.02717089,-0.060444463,0.046008736,-0.013550501,0.04982111,-0.022620251,-0.14648548,-0.0634082,-0.07433909,0.014497893,-0.053965494,-0.062459268,0.027845128,0.0033851597,-0.008427433,-0.012819001,-0.008809914,-0.03787092,-0.024571927,0.06647372,-0.15442225,0.0033556086,-0.0050765607,-0.015219653,0.045475025,0.055027995,-0.093345314,-0.04228607,-0.027523514,0.013605075,-0.10144757,0.06089652,0.09587606,0.01576467,-0.002081524,0.07492425,0.040061697,-0.049905017,0.05625711,-0.007144484,0.011636889,0.01605097,-0.08878179,0.06740853,0.13836893,-0.03335956,0.08