e29eb8e6-b968-4e1f-a44a-32dab832147b	2026-05-26 06:13:38+00	git	fix: wrap startCommand in sh -c to enable shell variable expansion	When Railway builds from a Dockerfile it executes startCommand in exec\nform (no shell), so \\${PORT:-8000} is passed literally to uvicorn and\ncrashes with "not a valid integer". Wrapping in sh -c forces a shell\nsubprocess that evaluates the expression before uvicorn receives it.\n\nApplied to backend/railway.toml, railway.toml, and nixpacks.toml.\n\nCo-Authored-By: Claude Sonnet 4.6 <noreply@anthropic.com>	episodic	null	\N	0.6	[0.028142428,0.09117994,0.003257641,-0.004772379,-0.003942938,-0.008133489,-0.010992992,0.08088003,-0.07130651,0.016610794,-0.044142608,-0.10552185,-0.034466818,0.055214178,0.024517516,0.005718602,0.033040963,0.0025804853,-0.0049124653,0.03697177,-0.102804214,0.08310467,-0.009434924,-0.010058693,-0.028614333,-0.06374828,-0.032838468,-0.053759348,-0.0430768,-0.006511289,-0.029647456,0.02347044,0.0008843229,-0.04935864,0.11968342,0.17533943,0.10446453,-0.09088372,-0.09246451,0.07144781,0.0070402445,-0.04975848,-0.05437779,0.08555699,-0.07191238,-0.038382336,0.015284634,-0.051875453,-0.028092975,0.018964197,-0.03840723,0.009136561,0.033807125,-0.055362117,-0.040148288,-0.070416294,-0.017904803,0.09165943,0.063703015,0.011635794,-0.031197846,0.0004282144,-0.015847376,-0.07519823,0.056651354,-0.059746165,-0.021779045,-0.027177181,-0.034490526,0.070467025,-0.01321618,-0.04661814,-0.07083337,0.00064823,-0.0031888804,0.12773812,0.03611361,0.01529666,-0.010418757,-0.03566356,-0.059861146,-0.042325564,-0.08259946,-0.093980126,0.0075188153,0.07716721,0.05037212,-0.015136967,0.057725478,0.01479069,-0.009011043,-0.033331275,-0.0492098,0.008857091,0.005485895,0.026821412,-0.056520194,0.036797,-0.046966735,0.027123287,-0.022990258,0.015642352,0.05087453,0.058842838,0.057012875,-0.048575833,0.0027194442,-0.008580995,0.0035139474,-0.12073768,0.016392514,-0.0019460919,-0.02880119,-0.015523155,-0.0019395347,0.07262062,0.013829683,